    const {java, cache} = this
    if (!order || order <= 1) order = 1
    let link
    let settings = this.getFromCacheObject("linpxSettings") || this.setDefaultSettings()
    if (!settings.DEBUG) link = this.getFromCache(urlIllustDetailed(illustId))

    if (!link) {
