function checkStatus(status) {
    if (eval(String(status)) === true) return "❤️"
    else return "🖤"
}

const serachSettingsName = {
    "SEARCH_AUTHOR": "🔍 搜索作者",
    "CONVERT_CHINESE": "🀄️ 繁简通搜",
}
const detailSettingsName = {
