const pictureSettingsName = {
    "PIC_SOURCE": "⏳ 图片解析",
    "PIC_LINK": "🔗 图片链接",
    "PIC_SIZE": "↔️ 图片大小",
}
const novelSettingsName = Object.assign({},
    serachSettingsName,
    detailSettingsName,
    catalogSettingsName,
    contentSettingsName,
    modeSettingsName,
    pictureSettingsName
)
const discoverSettingsName = {
    "SHOW_ADULT": "🔞 默认发现",
    "SHOW_ABOUT": "📚 书源相关",
}
const menuSettingsName = {
    "SHOW_DISCOVER": "⚙️ 发现设置",
